INSERT INTO `chatbot_at` (`id`, `category`, `keywords`, `response`) VALUES
(5, 'About', 'about,company,brand,arakutribe', 'At Araku Tribe, we offer coffee made from hand-picked beans of the Araku Valley, packaged with eco-friendly wheat bags preserving flavor and aroma. Each cup is a tribute to tradition and reflects the rich heritage of the Araku Tribe. How can you order?Step1 : Go to products page\r\nStep2: select the item you want to buy and click add to cart and then click buy.\r\nStep3: In cart page go to proceed to checkout and fill your details and finish the order by making payment.\r\nStep4: Tadaa! Your order will be placed and you will receive a email with order details and confirmation.'),
(6, 'Features', 'features,what do you provide,what we provide,services', 'We provide the finest coffee experience with authentic beans cultivated sustainably by the Araku tribes. Our products reflect tradition, biodiversity, and eco-friendly practices. Details: <a href=\"https://www.arakutribe.com/index.php\" target=\"_blank\">https://www.arakutribe.com/index.php</a>'),
(7, 'Authentic Coffee', 'authentic coffee,araku coffee,organic coffee', 'Araku coffee is cultivated without chemical fertilizers or pesticides by indigenous tribes, offering pure organic taste reflecting the land. More info: <a href=\"https://www.arakutribe.com/coffee_bag.php\" target=\"_blank\">https://www.arakutribe.com/coffee_bag.php</a>'),
(8, 'Coffee Culture', 'coffee culture,tribe culture', 'Cultivation with ancient methods and deep cultural significance makes Araku coffee unique. Discover the journey from seed to cup: <a href=\"https://www.arakutribe.com/coffee_about.php\" target=\"_blank\">https://www.arakutribe.com/coffee_about.php</a>'),
(10, 'Coffee Machines', 'coffee machines,machines', 'Coffee machines designed for home and business to brew authentic Araku coffee. Learn more: <a href=\"https://www.arakutribe.com/coffee_franchise.php\" target=\"_blank\">https://www.arakutribe.com/coffee_franchise.php</a>'),
(11, 'Products', 'products,product catalog,catalog', 'Explore aromatic coffee, eco-friendly cups, rustic mugs, and sustainable bags crafted by Araku artisans. Full range: <a href=\"https://www.arakutribe.com/coffee_products.php\" target=\"_blank\">https://www.arakutribe.com/coffee_products.php</a>'),
(12, 'Coffee Cup', 'tribal coffee cup,cup,cups', 'Tribal Coffee Cup - A rustic, eco-friendly cup. $259.00 ($2.59/unit), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_cup.php\" target=\"_blank\">https://www.arakutribe.com/coffee_cup.php</a>'),
(13, 'Coffee Cup', 'paper coffee cup,paper cup,sustainable cup', 'Paper Coffee Cup - A sustainable, earth-friendly cup. $289.00 ($2.89/unit), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_cup.php\" target=\"_blank\">https://www.arakutribe.com/coffee_cup.php</a>'),
(14, 'Coffee Cup', 'earthy coffee cup,warm tone cup', 'Earthy Coffee Cup - Crafted in warm and natural tones. $329.00 ($3.29/unit), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_cup.php\" target=\"_blank\">https://www.arakutribe.com/coffee_cup.php</a>'),
(15, 'Coffee Cup', 'coffee brown cup,coffee hue', 'Coffee Brown Cup - A rich, coffee-hued cup. $299.00 ($2.99/unit), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_cup.php\" target=\"_blank\">https://www.arakutribe.com/coffee_cup.php</a>'),
(16, 'Coffee Mug', 'stone carved mug,mug,mugs', 'Stone-Carved Mug - Rugged yet elegant, $499.00 ($4.99/unit), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_mug.php\" target=\"_blank\">https://www.arakutribe.com/coffee_mug.php</a>'),
(17, 'Coffee Mug', 'eco-friendly mud mug,sustainable mug', 'Eco-Friendly Mud Mug - Inspired by Araku’s rich coffee. $479.00 ($4.79/unit), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_mug.php\" target=\"_blank\">https://www.arakutribe.com/coffee_mug.php</a>'),
(18, 'Coffee Mug', 'handcrafted mud mug,mud mug,heritage mug', 'Handcrafted Mud Mug - Beautifully crafted reflecting heritage. $399.00 ($3.99/unit), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_mug.php\" target=\"_blank\">https://www.arakutribe.com/coffee_mug.php</a>'),
(19, 'Coffee Mug', 'tribal fusion mug,unique mug', 'Tribal Fusion Mug - Unique fusion of tribal artistry. $459.00 ($4.59/unit), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_mug.php\" target=\"_blank\">https://www.arakutribe.com/coffee_mug.php</a>'),
(20, 'Coffee Bag', 'jute coffee bag,jute bag,bag', 'Jute Coffee Bag - Rustic charm, $1499.00 ($14.99/32 oz), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_bag.php\" target=\"_blank\">https://www.arakutribe.com/coffee_bag.php</a>'),
(21, 'Coffee Bag', 'eco-friendly bag,sustainable bag', 'Eco-Friendly Bag - Responsibly crafted tradition bag. $1299.00 ($12.99/32 oz), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_bag.php\" target=\"_blank\">https://www.arakutribe.com/coffee_bag.php</a>'),
(22, 'Coffee Bag', 'cloth coffee bag,durable bag,reusable bag', 'Cloth Coffee Bag - Durable, reusable cloth bag. $1299.00 ($12.99/32 oz), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_bag.php\" target=\"_blank\">https://www.arakutribe.com/coffee_bag.php</a>'),
(23, 'Coffee Bag', 'paper coffee bag,sustainable paper bag', 'Paper Coffee Bag - Sustainable paper bag, fresh and aromatic. $1199.00 ($11.99/32 oz), 100 Units. Details: <a href=\"https://www.arakutribe.com/coffee_bag.php\" target=\"_blank\">https://www.arakutribe.com/coffee_bag.php</a>'),
(24, 'Coffee T-Shirt', 'tshirt,tshirts,t-shirt,shirt,shirts', 'Cotton t-shirt with tribal print, unisex sizes S–XXL. Price: ₹4.20. Details: <a href=\"https://www.arakutribe.com/coffee_tshirt.php\" target=\"_blank\">https://www.arakutribe.com/coffee_tshirt.php</a>'),
(25, 'Franchise Opportunities', 'join franchise,franchise opportunity,franchise partner', 'Join Araku Tribe franchise to share authentic coffee with business model, training, and branding support. Visit: <a href=\"https://www.arakutribe.com/coffee_franchise.php\" target=\"_blank\">https://www.arakutribe.com/coffee_franchise.php</a>'),
(26, 'Franchise Details', 'franchise investment,franchise cost', 'Investment: $7,000–$8,000 including powders, machines, branded cups. Full support and training provided. Details: <a href=\"https://www.arakutribe.com/coffee_franchise.php#id-add\" target=\"_blank\">https://www.arakutribe.com/coffee_franchise.php#id-add</a>'),
(27, 'Franchise Testimonials', 'franchise review,testimonial,partner feedback', '“Great team support! My store is now a go-to spot for coffee lovers.” – Rajesh P. “Customers love the premium coffee and brand.” – Sneha M. Read more: <a href=\"https://www.arakutribe.com/coffee_franchise.php#id-rev\" target=\"_blank\">https://www.arakutribe.com/coffee_franchise.php#id-rev</a>'),
(28, 'Client Feedback', 'client feedback,testimonials,customer reviews', 'Clients praise the premium quality and social impact of Araku Tribe coffee. More stories on homepage feedback section: <a href=\"https://www.arakutribe.com/index.php#feedback-section\" target=\"_blank\">https://www.arakutribe.com/index.php#feedback-section</a>'),
(29, 'Blog', 'blogs,articles,news,latest blog', 'Blogs highlight traditional coffee methods, organic cultivation, and community dedication. Latest: “Araku Coffee produced traditionally” (12 July 2025). Read more: <a href=\"https://www.arakutribe.com/coffee_about.php\" target=\"_blank\">https://www.arakutribe.com/coffee_about.php</a>'),
(30, 'Contact', 'contact,email,phone,support', 'Call (+91) 789-383-6529 or email info@arakutribe.com. Support hours Mon–Sat, 10 AM–6 PM IST. Contact page: <a href=\"https://www.arakutribe.com/coffee_contact.php\" target=\"_blank\">https://www.arakutribe.com/coffee_contact.php</a>'),
(31, 'Signup', 'signup,register,join', 'Sign up for exclusive offers and updates quickly and easily at <a href=\"https://www.arakutribe.com/coffee_signup.php\" target=\"_blank\">https://www.arakutribe.com/coffee_signup.php</a>'),
(32, 'Login', 'login,signin,account', 'Existing members can log in to manage orders and enjoy offers at <a href=\"https://www.arakutribe.com/coffee_login.php\" target=\"_blank\">https://www.arakutribe.com/coffee_login.php</a>'),
(33, 'Social Media', 'facebook,instagram,twitter,x,social', 'Follow us on Facebook <a href=\"https://www.facebook.com/people/Araku-Tribe-Coffee/61572935911579/\" target=\"_blank\">https://www.facebook.com/people/Araku-Tribe-Coffee/61572935911579/</a>, Instagram <a href=\"https://www.instagram.com/araku_tribe\" target=\"_blank\">https://www.instagram.com/araku_tribe</a>, Twitter/X <a href=\"https://x.com/university94155\" target=\"_blank\">https://x.com/university94155</a>'),
(34, 'Shipping', 'shipping,delivery', 'Delivery across India in 4–7 business days. Free shipping for orders above ₹999. Eco-friendly packaging with SMS & email tracking.'),
(35, 'Returns', 'return,refund,replacement', 'Returns/replacements accepted within 7 days for defective or incorrect products. Report issues within 48 hours. Refunds processed in 3–5 business days.'),
(36, 'Payments', 'payment,upi,card,net banking,cod', 'We accept UPI, debit/credit cards, net banking, and COD in select areas. Payments are securely processed.'),
(37, 'Fallback', 'default', 'Sorry, I didn’t understand that. Please ask about products, policies, franchise, or contact us. More info: <a href=\"https://www.arakutribe.com/\" target=\"_blank\">https://www.arakutribe.com/</a>'),
(57, 'Greetings', 'hi, hello, hey, good morning, good afternoon, yo', 'Hello! Welcome to Araku Tribe Coffee. How can I help you today?'),
(61, 'About', 'about,company,brand,arakutribe,ABOUT,COMPANY,BRAND,ARAKUTRIBE', 'Experience the Rich Heritage of Araku Coffee! Learn more: https://www.arakutribe.com/coffee_about.php'),
(62, 'Features', 'features,what do you provide,services,offerings,experiences,FEATURES,SERVICES,OFFERINGS,EXPERIENCES', 'We offer authentic Araku coffee, eco-friendly cups and bags, mugs, t-shirts, and more. See details: https://www.arakutribe.com/index.php'),
(63, 'Products', 'product,products,catalog,list,range,items,PRODUCT,PRODUCTS,CATALOG,ITEMS', 'Explore our full product range: www.arakutribe.com/coffee_products.php'),
(64, 'Coffee Cup', 'tribal coffee cup,cup,cups,paper cup,earthy cup,coffee brown cup,coffee cup,TRIBAL COFFEE CUP,CUP,CUPS,PAPER CUP,EARTHY CUP,COFFEE BROWN CUP,COFFEE CUP', 'Cups: Tribal ($259/100 units), Paper ($289/100 units), Earthy ($329/100), Coffee Brown ($299/100). Full cups info: https://www.arakutribe.com/coffee_cup.php'),
(65, 'Coffee Mug', 'mug,mugs,stone carved mug,eco-friendly mug,handcrafted mud mug,mud mug,heritage mug,unique mug,tribal fusion mug,MUG,MUGS,STONE CARVED MUG,ECO-FRIENDLY MUG,HANDCRAFTED MUD MUG,MUD MUG,HERITAGE MUG,UNIQUE MUG,TRIBAL FUSION MUG', 'Mugs: Stone-Carved ($499/100 units), Eco-Friendly Mud ($479/100), Handcrafted Mud ($399/100), Tribal Fusion ($459/100). All mugs: https://www.arakutribe.com/coffee_mug.php'),
(66, 'Coffee Bag', 'bag,bags,jute bag,jute coffee bag,eco-friendly bag,sustainable bag,cloth bag,cloth coffee bag,paper coffee bag,reusable bag,BAG,BAGS,JUTE BAG,JUTE COFFEE BAG,ECO-FRIENDLY BAG,SUSTAINABLE BAG,CLOTH BAG,CLOTH COFFEE BAG,PAPER COFFEE BAG,REUSABLE BAG', 'Bags: Jute ($1499/100 units), Eco-Friendly ($1299/100), Cloth ($1299/100), Paper ($1199/100). Complete bags info: https://www.arakutribe.com/coffee_bag.php'),
(67, 'Coffee T-Shirt', 'tshirt,tshirts,t-shirt,shirt,shirts,printed t-shirt,tribal t-shirt,TSHIRT,TSHIRTS,T-SHIRT,SHIRT,SHIRTS,PRINTED T-SHIRT,TRIBAL T-SHIRT', 'Tribal print t-shirts (S–XXL, ₹4.20, unisex): https://www.arakutribe.com/coffee_tshirt.php'),
(68, 'Coffee Machine', 'machine,machines,coffee machine,coffee machines,brewer,coffee maker,MACHINE,MACHINES,COFFEE MACHINE,COFFEE MACHINES,BREWER,COFFEE MAKER', 'Coffee machines for home/business, designed for authentic brewing: https://www.arakutribe.com/coffee_franchise.php'),
(69, 'Prices', 'price,prices,cost,pricing,amount,charge,fee,PRICE,PRICES,COST,PRICING,AMOUNT,CHARGE,FEE', 'Prices: Tribal Cup $259, Paper Cup $289, Earthy Cup $329, Coffee Brown Cup $299, Stone-Carved Mug $499, Eco-Friendly Mud Mug $479, Handcrafted Mud Mug $399, Tribal Fusion Mug $459, Jute Bag $1499, Eco-Friendly Bag $1299, Cloth Bag $1299, Paper Bag $1199, T-Shirt ₹4.20. See all products and prices: https://www.arakutribe.com/coffee_products.php'),
(70, 'Franchise Main', 'franchise,join franchise,franchise opportunity,franchise partner,franchise experience,franchise review,business,coffee business,FRANCHISE,JOIN FRANCHISE,FRANCHISE OPPORTUNITY,FRANCHISE PARTNER,FRANCHISE EXPERIENCE,FRANCHISE REVIEW,BUSINESS,COFFEE BUSINESS', 'Start your own Araku Tribe franchise! Details: https://www.arakutribe.com/coffee_franchise.php'),
(71, 'Franchise Details', 'franchise investment,franchise cost,franchise pricing,investment,cost,business cost,franchise details,FRANCHISE INVESTMENT,FRANCHISE COST,FRANCHISE PRICING,INVESTMENT,COST,BUSINESS COST,FRANCHISE DETAILS', 'Investment: $7,000–$8,000 incl. products/machines setup. More info: https://www.arakutribe.com/coffee_franchise.php#id-add'),
(72, 'Franchise Testimonials', 'franchise testimonial,testimonial,partner feedback,franchise testimonials,client review,partner review,FRANCHISE TESTIMONIAL,TESTIMONIAL,PARTNER FEEDBACK,FRANCHISE TESTIMONIALS,CLIENT REVIEW,PARTNER REVIEW', 'What our franchise partners say: “Great support from the team!”, “A rewarding investment!”, “Strong branding—my outlet is growing fast!” Read testimonials: https://www.arakutribe.com/coffee_franchise.php#id-rev'),
(73, 'Testimonials', 'feedback,testimonial,client feedback,customer reviews,client stories,TESTIMONIAL,CLIENT FEEDBACK,CUSTOMER REVIEWS,CLIENT STORIES', 'Sneha Rao: \"Our café takes pride in unique flavors, and Araku Coffee has exceeded expectations. The organic beans create a taste customers love. Stylish cups add premium touch.\" Vikram Shetty: \"Araku Coffee’s ethical sourcing and branded cups are Instagram-worthy, bringing in more customers.\" Harini Das: \"Boost in sales, strong earthy flavors, franchise support excellent, premium cups strong brand identity.\" Ramesh Varma: \"Premium beans, aroma, branded cups boost takeaway sales. Partnering was best decision.\"'),
(74, 'Blog', 'blog,blogs,article,news,latest blog,updates,BLOG,BLOGS,ARTICLE,NEWS,LATEST BLOG,UPDATES', 'Latest Blogs: Tradition, organic farming, sustainable methods — Araku Coffee produced using traditional methods (June/July/July 2025), rich biodiversity, harmony with land. Full blogs: https://www.arakutribe.com/coffee_about.php'),
(75, 'Contact', 'contact,email,phone,support,call,address,location,whatsapp,help,helpdesk,CONTACT,EMAIL,PHONE,SUPPORT,CALL,ADDRESS,LOCATION,WHATSAPP,HELP,HELPDESK', 'Phone: (+91) 789-383-6529 | Email: info@arakutribe.com | Contact page: https://www.arakutribe.com/coffee_contact.php'),
(76, 'Signup', 'signup,sign up,register,join,account create,register now,SIGNUP,SIGN UP,REGISTER,JOIN,ACCOUNT CREATE,REGISTER NOW', 'Create your account or sign up for offers: https://www.arakutribe.com/coffee_signup.php'),
(77, 'Login', 'login,signin,log in,sign in,account access,LOGIN,SIGNIN,LOG IN,SIGN IN,ACCOUNT ACCESS', 'Login and manage your orders here: https://www.arakutribe.com/coffee_login.php'),
(78, 'Social Media', 'facebook,instagram,twitter,x,youtube,social media,follow,sm,FACEBOOK,INSTAGRAM,TWITTER,X,YOUTUBE,SOCIAL MEDIA,FOLLOW,SM', 'Follow Araku Tribe: Facebook https://www.facebook.com/people/Araku-Tribe-Coffee/61572935911579/, Instagram https://www.instagram.com/araku_tribe, Twitter/X https://x.com/university94155'),
