(97, 'Coffee Bag', 'bag,bags,jute bag,jute coffee bag,eco-friendly bag,sustainable bag,cloth bag,cloth coffee bag,paper coffee bag,reusable bag', 'Bags: Jute USD 1499/100 units, Eco-Friendly USD 1299/100 units, Cloth USD 1299/100 units, Paper USD 1199/100 units. Details: https://www.arakutribe.com/coffee_bag.php'),
(98, 'Coffee T-Shirt', 'tshirt,tshirts,t-shirt,shirt,shirts,printed t-shirt,tribal t-shirt', 'Tribal print t-shirts available in sizes S to XXL. Price: ₹4.20. Details: https://www.arakutribe.com/coffee_tshirt.php'),
(99, 'Coffee Machine', 'machine,machines,coffee machine,coffee machines,brewer,coffee maker', 'Coffee machines designed for home and business authentic brewing. Learn more: https://www.arakutribe.com/coffee_franchise.php'),
(100, 'Prices', 'price,prices,cost,pricing,amount,charge,fee', 'Prices include: Tribal Cup $259, Paper Cup $289, Earthy Cup $329, Coffee Brown Cup $299, Stone-Carved Mug $499, Eco-Friendly Mud Mug $479, Handcrafted Mud Mug $399, Tribal Fusion Mug $459, Jute Bag $1499, Eco-Friendly Bag $1299, Cloth Bag $1299, Paper Bag $1199, T-Shirt ₹4.20. Full list: https://www.arakutribe.com/coffee_products.php'),
