(102, 'Franchise Details', 'franchise investment,franchise cost,franchise pricing,investment,cost,business cost,franchise details', 'Investment ranges from $7,000 to $8,000 including setup and products. Info: https://www.arakutribe.com/coffee_franchise.php#id-add'),
(103, 'Franchise Testimonials', 'franchise testimonial,testimonial,partner feedback,franchise testimonials,client review,partner review', 'Our franchise partners say: “Great support!”, “A rewarding investment!”, “Strong branding.” Read testimonials: https://www.arakutribe.com/coffee_franchise.php#id-rev'),
(104, 'Testimonials', 'feedback,testimonial,client feedback,customer reviews,client stories', 'Sneha Rao: Unique flavors and stylish cups attract coffee lovers. Vikram Shetty: Ethical sourcing and branded cups bring customers. Harini Das: Sales boost, strong flavors, excellent franchise support. Ramesh Varma: Premium beans, branded cups enhance takeaway sales.'),
