(160, 'About', 'about,company,brand,arakutribe,ABOUT,COMPANY,BRAND,ARAKUTRIBE', 'Araku Tribe is committed to bringing you authentic, sustainable coffee grown in the picturesque valleys of the Eastern Ghats. Our brand reflects passion for quality and indigenous heritage.To learn more about our story and mission, please visit [https://www.arakutribe.com/coffee_about.php](https://www.arakutribe.com/coffee_about.php).'),
(161, 'Features', 'features,feature,what do you provide,services,offerings,experiences', 'Our products include sustainably grown coffee, eco-friendly cups, handcrafted mugs, and ethically sourced merchandise. We prioritize quality and environmental responsibility.Explore all our unique features and learn how we contribute to community empowerment at [https://www.arakutribe.com/index.php](https://www.arakutribe.com/index.php).'),
(162, 'Products', 'products,product,catalog,range,list,items', 'Discover a wide range of premium coffee and merchandise crafted with care to suit your taste and lifestyle. Each item is a testament to our commitment to excellence.View our complete product range including coffee varieties, mugs, bags, and apparel here: [https://www.arakutribe.com/coffee_products.php](https://www.arakutribe.com/coffee_products.php).'),
(163, 'Coffee Cup', 'cup,cups,tribal coffee cup,paper cup,earthy cup,coffee brown cup', 'Our tribal coffee cups are designed to bring the rustic charm of Araku\'s heritage to your experience, featuring eco-friendly materials and unique styling.For detailed product information and ordering, visit [https://www.arakutribe.com/coffee_cup.php](https://www.arakutribe.com/coffee_cup.php).'),
(164, 'Coffee Mug', 'mug,mugs,stone carved mug,eco-friendly mug,handcrafted mug,tribal fusion mug', 'Handcrafted and stone-carved mugs blend tribal artistry with functionality, perfect for enjoying authentic Araku coffee.Explore the full collection and find your favorite at [https://www.arakutribe.com/coffee_mug.php](https://www.arakutribe.com/coffee_mug.php).'),
(165, 'Coffee Bag', 'bag,bags,jute bag,eco-friendly bag,cloth bag,paper bag', 'Our coffee bags are crafted using sustainable and traditional methods, providing fresh, aromatic storage options.Learn more about our eco-conscious packaging and options at [https://www.arakutribe.com/coffee_bag.php](https://www.arakutribe.com/coffee_bag.php).'),
(166, 'T-Shirt', 'tshirt,tshirts,t-shirt,printed t-shirt,tribal t-shirt,apparel', 'Wear your love for the tribe with our exclusive range of tribal printed t-shirts made with quality fabrics and unique designs.Available in multiple sizes; details and purchases at [https://www.arakutribe.com/coffee_tshirt.php](https://www.arakutribe.com/coffee_tshirt.php).'),
(167, 'Machine,Coffee Machine', 'machine,machines,coffee machine,brewer,coffee maker', 'Our coffee machines are designed for ease of use and consistent quality brewing, enhancing your coffee experience at home or business.For more details and how to acquire, visit [https://www.arakutribe.com/coffee_franchise.php](https://www.arakutribe.com/coffee_franchise.php).'),
(168, 'Prices', 'price,prices,cost,pricing,fee,charge', 'Our products are competitively priced to deliver great value without compromising on quality. Prices vary by product type and quantity.You can view the up-to-date pricing for all items here: [https://www.arakutribe.com/coffee_products.php](https://www.arakutribe.com/coffee_products.php).'),
(170, 'Testimonials', 'feedback,review,client stories', 'Customers appreciate our authentic flavors and excellent support. Hear what our partners say about the impact of Araku coffee on their business and culture.Read full testimonials here: [https://www.arakutribe.com/coffee_franchise.php#testimonials](https://www.arakutribe.com/coffee_franchise.php#testimonials).'),
(171, 'Blog', 'blog,news,update,articles', 'Stay updated with the latest news, stories, and coffee culture insights from the Araku tribe and our brewing techniques.Explore our blog at [https://www.arakutribe.com/coffee_blog.php](https://www.arakutribe.com/coffee_blog.php).'),
(172, 'Contact', 'contact,support,email,phone,address', 'Need assistance or have questions? Reach out to us via phone, email, or visiting our location in Araku Valley.Contact details and map available at [https://www.arakutribe.com/coffee_contact.php](https://www.arakutribe.com/coffee_contact.php).'),
(173, 'Signup', 'signup,register,join', 'Create your Araku Tribe account today to enjoy exclusive deals and access to special offers.Sign up here: [https://www.arakutribe.com/coffee_signup.php](https://www.arakutribe.com/coffee_signup.php).'),
(174, 'Login', 'login,signin,account', 'Access your account easily anytime to manage orders and preferences.Login here: [https://www.arakutribe.com/coffee_login.php](https://www.arakutribe.com/coffee_login.php).'),
