(181, 'Product Page', 'products', 'Browse all available products: [https://www.arakutribe.com/coffee_products.php](https://www.arakutribe.com/coffee_products.php).Find your favorite blend or merchandise.'),
(182, 'Franchise Page', 'franchise', 'Interested in partnership? Details at: [https://www.arakutribe.com/coffee_franchise.php](https://www.arakutribe.com/coffee_franchise.php).Grow with the Araku Tribe brand.'),
(183, 'Contact Page', 'contact', 'Get in touch for support or inquiries: [https://www.arakutribe.com/coffee_contact.php](https://www.arakutribe.com/coffee_contact.php).We\'re always here to help.'),
(184, 'Shipping', 'shipping,delivery', 'Our shipping services cover all of India with typical delivery in 4-7 business days.Track your orders and expect eco-friendly packaging. More info: [https://www.arakutribe.com/coffee_contact.php](https://www.arakutribe.com/coffee_contact.php).'),
(185, 'Returns', 'returns,return policy,refund,replacement', 'Returns and replacements are accepted within 7 days for defective or incorrect products.Refunds are processed within 3-5 business days. For details, visit [https://www.arakutribe.com/coffee_contact.php](https://www.arakutribe.com/coffee_contact.php).'),
(186, 'Payments', 'payments,upi,credit card,debit card,net banking,cod', 'We accept multiple payment methods including UPI, credit/debit cards, net banking, and COD.All transactions are secure and reliable. Learn more: [https://www.arakutribe.com/coffee_products.php](https://www.arakutribe.com/coffee_products.php).'),
(187, 'Fallback', 'unknown,default,error,not found', 'I\'m sorry, I didn\'t understand that. Please ask about our products, prices, franchise, or how to contact us.For more info, visit [https://www.arakutribe.com](https://www.arakutribe.com).'),
(188, 'Coffee Cup', 'tribal coffee cup,cup,cups,paper cup,earthy cup,coffee brown cup,coffee cup', 'Cups: Tribal USD 259/100 units, Paper USD 289/100 units, Earthy USD 329/100 units, Coffee Brown USD 299/100 units. Details: https://www.arakutribe.com/coffee_cup.php'),
(193, 'About', 'about,company,brand,arakutribe', 'At Araku Tribe, we provide sustainably grown coffee from the pristine Araku Valley. We celebrate tribal heritage and traditional cultivation methods. Learn more at [https://www.arakuibe.com/coffee_about.php](https://www.arakuibe.com/coffee_about.php).'),
(194, 'About', 'arakutribe story,heritage,tradi tion', 'Our coffee is cultivated with love and respect for the environment by indigenous tribes. Join us in preserving the rich heritage of Araku Coffee.'),
(195, 'Features', 'features,what do you offer,services', 'We offer authentic Araku coffee, eco-friendly cups, handcrafted mugs, bags, and apparel. Our products blend tradition with modern sustainability. More details at [https://www.arakuibe.com/index.php](https://www.arakuibe.com/index.php).'),
(196, 'Features', 'eco friendly,sustainable,quality', 'Our commitment is to quality, ethical sourcing, and sustainable practices that support tribal communities.'),
(197, 'Products', 'products,product list,catalog', 'Explore our range including aromatic coffee beans, paper and clay cups, stone and mud mugs. Everything crafted by Araku artisans. Full catalog at [https://www.arakuibe.com/coffee_products.php](https://www.arakuibe.com/coffee_products.php).'),
