(257, 'T-Shirt', 'cotton shirts,apparel', 'Comfortable, eco-friendly cotton shirts representing tribal art and culture.'),
(258, 'Coffee Machine', 'coffee machine,brewer', 'Our coffee machines blend tradition and technology, suited for home and business use. Learn more at https://www.arakuibe.com/coffee_franchise.php'),
(259, 'Coffee Machine', 'business machines,home coffee maker', 'Experience professional-grade brewing right at home or in your café.'),
(260, 'Prices', 'price,prices,cost', 'Our products are priced fairly to reflect authentic quality. Cup prices start at $259 per 100 units, mugs from $399, bags from $1199, and T-shirts at ₹4.20. Check full list at https://www.arakuibe.com/coffee_products.php'),
(261, 'Prices', 'discounts,offers', 'Sign up for exclusive offers and seasonal discounts, available for new members.'),
(264, 'Testimonials', 'feedback,reviews', 'Our partners and customers love the unique flavors and organizational support. Read their stories and testimonials at https://www.arakuibe.com/coffee_franchise.php#testimonials'),
(265, 'Testimonials', 'customer reviews', 'Clients highlight our coffee’s rich aroma, community focus, and consistent quality.'),
(266, 'Blog', 'blog,news,update', 'Stay informed with stories about tribal farming, coffee culture, and sustainability. Visit our blog at https://www.arakuibe.com/coffee_about.php'),
(267, 'Blog', 'articles,events', 'Read about latest events, coffee harvesting, and eco-friendly practices through our updates.'),
(268, 'Contact', 'contact,email,phone,address', 'Contact us at +91 789-383-6529 or email info@arakuibe.com. Visit our location in Araku Valley or online support at https://www.arakuibe.com/coffee_contact.php'),
(269, 'Contact', 'support,help', 'Our team is available Mon-Sat 10am-6pm IST for all customer support queries.'),
(270, 'Signup', 'signup,join,register', 'Create your Araku Tribe account to access exclusive deals and offers. Sign up now at https://www.arakuibe.com/coffee_signup.php'),
(271, 'Signup', '', 'Be the first to know about new products and promotions by joining the tribe.'),
(272, 'Login', 'login,signin,account', 'Access your account securely to place new orders or track existing ones at https://www.arakuibe.com/coffee_login.php'),
(273, 'Login', '', 'Manage your preferences and subscriptions easily through our online platform.');
INSERT INTO `chatbot_at` (`id`, `category`, `keywords`, `response`) VALUES
(274, 'Facebook', 'facebook', 'Follow Araku Tribe on Facebook: https://www.facebook.com/arakutribe. Join our community for updates and events.'),
(275, 'Instagram', 'instagram', 'See our coffee journey and tribal stories on Instagram: https://www.instagram.com/arakutribe'),
(276, 'Twitter', 'twitter', 'Stay connected with us on Twitter: https://twitter.com/arakutribe'),
(277, 'Social Media', 'social media', 'Follow us on Facebook, Instagram, and Twitter to stay updated with the latest from Araku Tribe.'),
(278, 'Home', 'home', 'Visit Araku Tribe homepage: https://www.arakuibe.com/index.php. Experience the rich heritage and offerings.'),
(279, 'About Us', 'about us', 'Learn more about our history and philosophy at https://www.arakuibe.com/coffee_about.php'),
(280, 'Products', 'products', 'Browse our complete product range at https://www.arakuibe.com/coffee_products.php'),
(282, 'Contact Us', 'contact us', 'Contact Araku Tribe customer support at https://www.arakuibe.com/coffee_contact.php'),
(283, 'Shipping', 'shipping,delivery', 'We ship across India with eco-friendly packaging. Delivery typically takes 4-7 business days. Track your order at https://www.arakuibe.com/coffee_contact.php'),
(284, 'Shipping', '', 'Free shipping on orders over ₹999. We strive for timely and secure deliveries.'),
(285, 'Returns', 'returns,refund,exchange', 'Returns and exchanges are accepted within 7 days for defective or incorrect products.'),
(286, 'Returns', '', 'Refunds are processed within 3-5 business days after approval. Details at https://www.arakuibe.com/coffee_contact.php'),
(287, 'Payments', 'payments,upi,card,net banking,cod', 'We accept UPI, debit/credit cards, net banking, and Cash on Delivery in select areas.'),
(288, 'Payments', '', 'All payments are processed securely via trusted gateways. Learn more at https://www.arakuibe.com/coffee_products.php'),
(289, 'Fallback', 'unknown,error,default', 'Sorry, I did not understand your query. Please ask about products, prices, franchise, or contact us.'),
(290, 'Fallback', '', 'Visit our website for more info: https://www.arakuibe.com'),
(291, 'Greetings', 'hi, hello, hey, good morning, good afternoon, yo', 'Hello! Welcome to Hayward University. How can I help you today?');
INSERT INTO `chatbot_ats` (`id`, `category`, `keywords`, `response`) VALUES
(1, 'General', 'about araku tribe, who are you, coffee origin', 'Araku Tribe Coffee offers delicious coffee made from rich, hand-picked beans of the Araku Valley.'),
(2, 'Product', 'authentic araku coffee, organic coffee, sustainable coffee', 'Our coffee is proudly cultivated by the indigenous Araku tribes through traditional, chemical-free, and sustainable farming techniques. This not only preserves the purity and natural flavor of the beans but also protects the soil, water, and biodiversity of the Araku Valley, ensuring a healthier environment and a more authentic cup of coffee.'),
(3, 'Culture', 'tribal culture, coffee traditions, tribal coffee story', 'The Araku tribe’s coffee culture centers around ancient organic farming and tradition.Our coffee is proudly cultivated by the indigenous Araku tribes through traditional, chemical-free, and sustainable farming techniques. This not only preserves the purity and natural flavor of the beans but also protects the soil, water, and biodiversity of the Araku Valley, ensuring a healthier environment and a more authentic cup of coffee.'),
(4, 'Business', 'franchise, coffee franchise, start coffee business', 'Experience the rich taste of Araku Tribe Coffee—crafted through sustainable, eco-friendly farming by indigenous communities. Start your own franchise today for just $7000 and share this authentic coffee culture in your city!'),
(6, 'Contact', 'contact, phone, email, address', 'Contact us: +91-7893-836-529\r\nEmail us : info@arakutribe.com\r\nOur address: Araku Valley, Visakhapatnam.'),
(7, 'General', 'about araku coffee, araku tribe heritage, araku coffee story', 'Araku Tribe Coffee is grown in the lush valleys of Araku, honoring indigenous farmers who have perfected coffee cultivation for generations. Each bean is produced using sustainable methods, ensuring purity, tradition, and exceptional flavor thanks to the unique climate and rich soil of the Eastern Ghats. Every sip is a celebration of heritage, sustainability, and excellence.'),
(8, 'Product', 'sustainable coffee, organic farming, regenerative agriculture, eco-friendly araku coffee', 'Our coffee is cultivated with respect for nature, using organic fertilizers and natural pest control. Indigenous Araku tribal farmers employ traditional, regenerative agriculture techniques that maintain soil health and biodiversity, yielding a coffee renowned for its authentic taste and environmental benefits.'),
(9, 'Community', 'farmer empowerment, fair trade, ethical sourcing, tribal cooperative', 'Araku Tribe Coffee supports tribal farmers through fair-trade practices, better wages, training, and sustainable agriculture resources. By choosing Araku coffee, customers help empower local communities and promote ethical, socially responsible coffee production.'),
(10, 'Culture', 'tradition, araku tribe, indigenous farming, coffee culture', 'The Araku Tribe’s legacy is rooted in centuries-old organic coffee farming, passed down through generations. Their cooperative model unites thousands of small-scale farmers, preserving cultural heritage while producing coffee celebrated worldwide for its quality and sustainability.'),
(11, 'Sustainability', 'eco-friendly packaging, biodegradable wheat bags, environmental responsibility', 'Our coffee is packed in eco-friendly, biodegradable wheat bags to preserve freshness and minimize environmental impact. Every step in our farm-to-cup process upholds our commitment to sustainability and responsible stewardship of nature.'),
(12, 'Quality', 'quality control, handpicked beans, roasting process, premium coffee', 'Quality is central to Araku Tribe Coffee. We handpick each cherry and carefully monitor roasting to enhance natural richness and aroma, guaranteeing a premium brew whether you enjoy espresso, cappuccino, or filter coffee.'),
(13, 'Blog', 'araku coffee news, sustainable farming, latest updates, organic cultivation', 'Araku Coffee’s journey is documented through our blog, sharing stories of sustainable farming, organic cultivation, and the dedication of the Araku tribe to preserving both culture and environment.'),
(14, 'Experience', 'join araku tribe, coffee experience, legacy, ethical sourcing', 'Araku Tribe Coffee invites coffee enthusiasts, business partners, and ethical consumers to be part of a legacy—supporting heritage, excellence, and sustainability with every cup.'),
(15, 'Franchise', 'franchise, coffee franchise, how to open franchise, get franchise, start franchise', 'You can partner with Araku Tribe Coffee to open your own franchise, bringing authentic Araku coffee to your city. We blend tradition, sustainability, and entrepreneurship for a unique business opportunity.'),
(16, 'Franchise', 'franchise benefits, franchise support, business model, franchise features, why choose araku franchise', 'Araku Tribe Coffee franchise offers premium coffee powders, state-of-the-art coffee machines, branded café setups, and end-to-end support in training, operations, and marketing. Enjoy high profitability with strong customer engagement and seamless operations.'),
(17, 'Franchise', 'franchise investment, cost, franchise fee, capital requirement, area needed', 'Typical investment for an Araku Tribe Coffee franchise can range from ₹2 lakh to ₹10 lakh, depending on outlet size and model. Area requirements vary from 100 to 1200 sq.ft., and franchise fees are often minimal or waived for the first year. No royalty fees or security deposit are required for select models.'),
(18, 'Franchise', 'sustainable franchise, fair trade business, tribal community support, ethical business', 'By partnering with Araku Tribe Coffee, you help empower tribal communities through fair trade and ethical sourcing. Our sustainable model ensures every franchise outlet supports indigenous farmers and promotes eco-friendly practices.'),
(19, 'Franchise', 'franchise process, application steps, how to apply for franchise, franchise procedure, franchise approval', 'Interested in an Araku Tribe Coffee franchise? Submit an inquiry, undergo evaluation, receive franchise documents, attend interviews, select a site, get training, set up your store, and open your business with ongoing brand support.'),
(20, 'Franchise', 'franchise feedback, partner experiences, franchise testimonials', 'Our franchise partners appreciate premium quality, dedicated support, and a proven business model. Franchisee feedback highlights seamless business growth and strong brand reputation.'),
(21, 'Contact', 'contact, phone number, call us, customer care, support', 'You can reach Araku Tribe Coffee by phone at (+91) 789-383-6529 for any queries about products, orders, or partnerships.'),
(22, 'Contact', 'email, write to us, message, customer support email', 'Send your questions or messages to info@arakutribe.com. We typically respond within 24 hours.'),
(23, 'Contact', 'address, office location, visit us, where are you', 'Our office is located at Araku Valley, Visakhapatnam. You are welcome to contact or visit us there for more information.'),
(24, 'Contact', 'contact details, reach out, communication', 'For comprehensive contact, call +91-7893-836-529 or email info@arakutribe.com. We are committed to assisting you promptly and efficiently.'),
(25, 'Product', 'coffee cups, araku cups, eco-friendly cups, coffee drinkware', 'Sip sustainably with Araku Tribe’s eco-friendly cups—crafted with tribal-inspired designs and planet-friendly materials. 🌿✨ From rich aromatic coffee to eco-friendly cups and rustic bags, we’ve got something special for every coffee lover.\r\n•Tribal Coffee Cup – Rustic & eco-friendly charm – $259.00 / $2.59 per unit\r\n•Paper Coffee Cup – Sustainable & earth-friendly – $289.00 / $2.89 per unit\r\n•Earthy Coffee Cup – Warm, natural-toned design – $329.00 / $3.29 per unit\r\n•Coffee Brown Cup – Simple yet rich coffee hues – $299.00 / $2.99 per unit\r\n💡Order Now: Visit the Products Page to explore and bring home the authentic taste & craft of Araku Tribe.\r\n How can you order?Step1 : Go to products page\r\nStep2: select the item you want to buy and click add to cart and then click buy.\r\nStep3: In cart page go to proceed to checkout and fill your details and finish the prder by making payment.\r\nStep4: Tadaa! Your order will be placed and you will receive a email with order details and confirmation.\r\n'),
(26, 'Product', 'tshirts, araku tribe tshirts, coffee branding tshirts, apparel', 'Wear the spirit of Araku Tribe! 🌿✨ Our stylish T-shirts blend premium comfort with unique tribal designs. Explore the Products Page to order yours today!'),
(27, 'Product', 'coffee bags, araku coffee bags, eco-friendly coffee packaging, jute bags', 'Bring home the authentic touch of Araku 🌿—our eco-friendly jute & cloth coffee bags keep your coffee fresh while reflecting rustic tribal elegance. Explore the Products Page to order today!'),
(28, 'Product', 'coffee mugs, araku mugs, tribal mugs, handcrafted mugs', 'Explore Araku Tribe’s Exclusive Collection ✨\r\nExperience the heritage of the Araku Valley in every product—crafted with care, tradition, and sustainability. From rich aromatic coffee to eco-friendly cups and rustic bags, we’ve got something special for every coffee lover. 🌿☕\r\n•Tribal Coffee Cup – Rustic & eco-friendly charm – $259.00 / $2.59 per unit\r\n•Stone-Carved Mug – Rugged yet elegant design – $499.00 / $4.99 per unit\r\n•Earthy Coffee Cup – Crafted in warm, natural tones – $329.00 / $3.29 per unit\r\n•Coffee Brown Cup – A rich, coffee-hued style – $299.00 / $2.99 per unit\r\n•Eco-Friendly Mud Mug – Inspired by Araku’s rich coffee culture – $479.00 / $4.79 per unit\r\n•Handcrafted Mud Mug – Beautifully made with tribal heritage – $399.00 / $3.99 per unit\r\n•Tribal Fusion Mug – Unique blend of tribal artistry – $459.00 / $4.59 per unit\r\n✨ Explore more on our Products Page and order your favorites today!'),
(29, 'General', 'hi, hello, hey, good morning, good afternoon, good evening', 'Hello! How can I assist you today? ☕'),
(31, 'General', 'bye, goodbye, see you, talk later, take care', 'Goodbye! Have a wonderful day and enjoy your coffee! ☕'),
(35, 'General', 'help me, support', 'Sure! What do you need help with? I can answer questions about coffee, products, franchises, and contact info.'),
(36, 'General', 'thanks bye, thank you bye', 'Thank you! Looking forward to chatting again. Have a great day! ☕');
