('c_coffee_about3_te3b05a82', 'coffee_about3', 'Section: Rooted in tradition, made for today', 123, 65, 'From biodegradable wheat-bag packaging to a smaller footprint in processing and distrib...', 'textarea', NULL, 'From biodegradable wheat-bag packaging to a smaller footprint in processing and distribution, every part of our business follows our commitment to the environment. Great coffee should taste good and do good, for people and the planet.', 'From biodegradable wheat-bag packaging to a smaller footprint in processing and distribution, every part of our business follows our commitment to the environment. Great coffee should taste good and do good, for people and the planet.', NULL, 'Change the words. Keep a similar length so it fits the design.', 'About | Section: Rooted in tradition, made for today', '2026-10-04 12:31:20', NULL),
('c_coffee_about3_te91ee515', 'coffee_about3', 'Section: Experience the rich heritage of Araku coffee.', 121, 41, 'At Araku Tribe we bring you coffee grown in the lush valleys of Araku, a tribute to the...', 'textarea', NULL, 'At Araku Tribe we bring you coffee grown in the lush valleys of Araku, a tribute to the indigenous farmers who have mastered coffee cultivation for generations. The unique climate, rich soil and natural shade of the Eastern Ghats give it its exceptional flavour.', 'At Araku Tribe we bring you coffee grown in the lush valleys of Araku, a tribute to the indigenous farmers who have mastered coffee cultivation for generations. The unique climate, rich soil and natural shade of the Eastern Ghats give it its exceptional flavour.', NULL, 'Change the words. Keep a similar length so it fits the design.', 'About | Section: Experience the rich heritage of Araku coffee.', '2026-10-04 12:31:20', NULL),
