('hs_bg', 'global', 'Home slider', 25, 1, 'Slider backgrounds', 'select', NULL, 'collage', 'collage', 'collage|photo', 'collage = a calm showcase wall of a few large, straight product tiles: on the right of the Araku Tribe slide (all ranges mixed), and as a clear wall of that range on the left of each range slide, with a soft shadow behind the text (no box). photo = the old single photos.', 'Home page slider: Araku Tribe slide | Coffee Bags slide | Coffee Cups slide | Coffee Mugs slide | T-Shirts slide', '2026-10-04 17:36:42', NULL),
('hs_dim', 'global', 'Home slider', 25, 2, 'Collage darkness (%)', 'number', NULL, '72', '72', '30,95', 'How dark the area behind the text is; it fades out towards the product tiles. Higher = text easier to read. 60-80 works well.', 'Home page slider backgrounds', '2026-10-04 17:36:42', NULL),
('hs_move', 'global', 'Home slider', 25, 3, 'Collage gently breathes', 'toggle', NULL, '1', '1', NULL, 'The product photos zoom in and out very slowly, so the slide feels alive without looking busy.', 'Home page slider backgrounds', '2026-10-04 17:36:42', NULL),
('hs_style', 'global', 'Home slider', 25, 4, 'Range slide look', 'select', NULL, 'floating', 'floating', 'floating|fan|pattern|wall', 'How the Bags, Cups, Mugs and T-shirts slides show their products. floating = four large tilted cards around the featured product; fan = two tall cards fanned out behind it; pattern = a faint product pattern over the whole slide; wall = a grid of clear tiles on the left with a soft shadow behind the text. The Araku Tribe slide keeps its own wall.', 'Home page slider: Coffee Bags slide | Coffee Cups slide | Coffee Mugs slide | T-Shirts slide', '2026-10-04 17:36:42', NULL),
('h_bg', 'global', 'Header', 5, 1, 'Header background', 'color', '--header-bg', '#FFFFFF', '#FFFFFF', NULL, 'Background of the logo / HOT DEALS / AI AGENT row.', 'Logo row behind the logo, HOT DEALS, AI AGENT and the icons', '2026-10-03 18:22:17', NULL),
